import math
from collections import Counter

def entropy(s):
    """Shannon entropy in bits per character: how unpredictable the text is."""
    n = len(s)
    return 0.0 - sum(c / n * math.log2(c / n) for c in Counter(s).values())

def score(query):
    first = query.split(".")[0]
    return len(query), len(first), round(entropy(first), 2)

for q in ["www.example.com", "login.example.net",
          "mzxw6ytboi2dcmrtgq3tmnzy.t.example.net"]:
    print(q, score(q))
