from dataclasses import dataclass

@dataclass
class Conn:
    requests: int = 0
    cancelled: int = 0
    over_limit: int = 0          # attempts to exceed the stream limit

def on_headers(c, open_streams, limit=100):
    if open_streams >= limit:
        c.over_limit += 1
        return "GOAWAY now" if c.over_limit > 3 else "refuse stream"
    c.requests += 1
    return "serve"

def on_rst_stream(c):
    c.cancelled += 1
    if c.requests > 100 and c.cancelled / c.requests > 0.5:
        return "GOAWAY now, close TCP"
    return "ok"

browser, bot = Conn(requests=150, cancelled=6), Conn(requests=150, cancelled=149)
print(on_rst_stream(browser))
print(on_rst_stream(bot))

table inet firewall {
    chain inbound {
        # By default, drop all traffic unless a rule below accepts it
        type filter hook input priority 0; policy drop;

        # Stateful core: replies to known connections pass, junk is dropped
        ct state vmap { established : accept, related : accept, invalid : drop }

        iifname lo accept                     # loopback
        icmpv6 type { nd-neighbor-solicit, nd-router-advert, nd-neighbor-advert } accept   # IPv6 neighbour discovery
        tcp dport { 22, 80, 443 } accept      # the only new connections allowed

        # log prefix "[nftables] Inbound Denied: " counter drop
    }
    chain forward {
        type filter hook forward priority 0; policy drop;   # not a router
    }
}

